BEGIN;
CREATE TABLE IF NOT EXISTS forge_events (id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id text NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,episode_id text REFERENCES episodes(id) ON DELETE RESTRICT,sequence_no bigserial UNIQUE NOT NULL,type text NOT NULL,version integer NOT NULL CHECK (version > 0),schema jsonb NOT NULL DEFAULT '{}'::jsonb,payload jsonb NOT NULL DEFAULT '{}'::jsonb,aggregate_type text NOT NULL,aggregate_id text,provenance jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_events_tenant_sequence_idx ON forge_events(tenant_id,sequence_no);
CREATE INDEX IF NOT EXISTS forge_events_project_created_idx ON forge_events(project_id,created_at DESC);
CREATE TABLE IF NOT EXISTS forge_event_subscriptions (id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id text REFERENCES projects(id) ON DELETE RESTRICT,endpoint_url text NOT NULL,secret_ciphertext text NOT NULL,event_types text[] NOT NULL DEFAULT '{}',ordered boolean NOT NULL DEFAULT false,rate_limit_per_second integer NOT NULL DEFAULT 10 CHECK (rate_limit_per_second BETWEEN 1 AND 1000),max_concurrency integer NOT NULL DEFAULT 4 CHECK (max_concurrency BETWEEN 1 AND 100),active boolean NOT NULL DEFAULT true,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_event_subscriptions_scope_idx ON forge_event_subscriptions(tenant_id,project_id,active);
CREATE TABLE IF NOT EXISTS forge_event_deliveries (id text PRIMARY KEY,event_id text NOT NULL REFERENCES forge_events(id) ON DELETE RESTRICT,subscription_id text NOT NULL REFERENCES forge_event_subscriptions(id) ON DELETE RESTRICT,tenant_id text NOT NULL REFERENCES tenants(id) ON DELETE RESTRICT,project_id text NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,sequence_no bigint NOT NULL,status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','IN_FLIGHT','RETRY','SUCCEEDED','FAILED','CANCELLED','DEAD_LETTER')),attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),available_at timestamptz NOT NULL DEFAULT now(),lease_token text,lease_until timestamptz,worker_id text,last_error text,last_response_status integer,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,subscription_id));
CREATE INDEX IF NOT EXISTS forge_event_deliveries_claim_idx ON forge_event_deliveries(status,available_at,sequence_no);
CREATE INDEX IF NOT EXISTS forge_event_deliveries_subscription_idx ON forge_event_deliveries(subscription_id,sequence_no,status);
CREATE INDEX IF NOT EXISTS forge_event_deliveries_tenant_idx ON forge_event_deliveries(tenant_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS forge_event_delivery_attempts (id text PRIMARY KEY,delivery_id text NOT NULL REFERENCES forge_event_deliveries(id) ON DELETE RESTRICT,subscription_id text NOT NULL REFERENCES forge_event_subscriptions(id) ON DELETE RESTRICT,attempt integer NOT NULL,status text NOT NULL,response_status integer,error_code text,latency_ms integer CHECK (latency_ms >= 0),started_at timestamptz NOT NULL,finished_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS forge_event_delivery_attempts_rate_idx ON forge_event_delivery_attempts(subscription_id,started_at DESC);
CREATE TABLE IF NOT EXISTS forge_event_dlq (delivery_id text PRIMARY KEY REFERENCES forge_event_deliveries(id) ON DELETE RESTRICT,reason text NOT NULL,quarantined_at timestamptz NOT NULL DEFAULT now(),released_at timestamptz,release_reason text);
CREATE OR REPLACE FUNCTION forge_event_tenant_guard() RETURNS trigger AS $$ DECLARE project_tenant text; BEGIN SELECT tenant_id INTO project_tenant FROM projects WHERE id=NEW.project_id; IF project_tenant IS NULL OR project_tenant <> NEW.tenant_id THEN RAISE EXCEPTION 'event tenant does not match project' USING ERRCODE='23514'; END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_event_tenant_guard ON forge_events;
CREATE TRIGGER forge_event_tenant_guard BEFORE INSERT OR UPDATE OF project_id,tenant_id ON forge_events FOR EACH ROW EXECUTE FUNCTION forge_event_tenant_guard();
CREATE OR REPLACE FUNCTION forge_capture_event(p_type text,p_project_id text,p_episode_id text,p_aggregate_type text,p_aggregate_id text,p_payload jsonb) RETURNS text AS $$ DECLARE event_id text; tenant text; BEGIN SELECT tenant_id INTO tenant FROM projects WHERE id=p_project_id; IF tenant IS NULL THEN RAISE EXCEPTION 'event project not found'; END IF; event_id := 'evt_' || md5(random()::text || clock_timestamp()::text || p_type || coalesce(p_aggregate_id,'')); INSERT INTO forge_events(id,tenant_id,project_id,episode_id,type,version,schema,payload,aggregate_type,aggregate_id,provenance) VALUES(event_id,tenant,p_project_id,p_episode_id,p_type,1,'{}'::jsonb,p_payload,p_aggregate_type,p_aggregate_id,jsonb_build_object('capture','database-trigger')); INSERT INTO forge_outbox(topic,aggregate_type,aggregate_id,payload) VALUES('event.created','forge_event',event_id,jsonb_build_object('eventId',event_id)); RETURN event_id; END; $$ LANGUAGE plpgsql;
CREATE OR REPLACE FUNCTION forge_episode_event_trigger() RETURNS trigger AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.state IS DISTINCT FROM OLD.state THEN PERFORM forge_capture_event('episode.state.changed',NEW.project_id,NEW.id,'episode',NEW.id,jsonb_build_object('episodeId',NEW.id,'projectId',NEW.project_id,'state',NEW.state,'revision',NEW.revision)); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_episode_event_capture ON episodes; CREATE TRIGGER forge_episode_event_capture AFTER UPDATE OF state ON episodes FOR EACH ROW EXECUTE FUNCTION forge_episode_event_trigger();
CREATE OR REPLACE FUNCTION forge_job_event_trigger() RETURNS trigger AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status AND NEW.project_id IS NOT NULL THEN PERFORM forge_capture_event('job.state.changed',NEW.project_id,NEW.episode_id,'job',NEW.id,jsonb_build_object('jobId',NEW.id,'projectId',NEW.project_id,'kind',NEW.kind,'status',NEW.status,'attempts',NEW.attempts)); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_job_event_capture ON forge_jobs; CREATE TRIGGER forge_job_event_capture AFTER UPDATE OF status ON forge_jobs FOR EACH ROW EXECUTE FUNCTION forge_job_event_trigger();
CREATE OR REPLACE FUNCTION forge_provider_run_event_trigger() RETURNS trigger AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN PERFORM forge_capture_event('provider_run.state.changed',(SELECT project_id FROM episodes WHERE id=NEW.episode_id),NEW.episode_id,'provider_run',NEW.id,jsonb_build_object('providerRunId',NEW.id,'episodeId',NEW.episode_id,'status',NEW.status,'provider',NEW.provider)); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_provider_run_event_capture ON provider_runs; CREATE TRIGGER forge_provider_run_event_capture AFTER UPDATE OF status ON provider_runs FOR EACH ROW EXECUTE FUNCTION forge_provider_run_event_trigger();
CREATE OR REPLACE FUNCTION forge_publish_event_trigger() RETURNS trigger AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN PERFORM forge_capture_event('publish.state.changed',(SELECT project_id FROM episodes WHERE id=NEW.episode_id),NEW.episode_id,'publish_run',NEW.id,jsonb_build_object('publishRunId',NEW.id,'episodeId',NEW.episode_id,'status',NEW.status,'destination',NEW.destination)); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_publish_event_capture ON publish_runs; CREATE TRIGGER forge_publish_event_capture AFTER UPDATE OF status ON publish_runs FOR EACH ROW EXECUTE FUNCTION forge_publish_event_trigger();
CREATE OR REPLACE FUNCTION forge_approval_event_trigger() RETURNS trigger AS $$ BEGIN PERFORM forge_capture_event('approval.created',(SELECT project_id FROM episodes WHERE id=NEW.episode_id),NEW.episode_id,'approval',NEW.id,jsonb_build_object('approvalId',NEW.id,'episodeId',NEW.episode_id,'stage',NEW.stage,'decision',NEW.decision)); RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_approval_event_capture ON approvals; CREATE TRIGGER forge_approval_event_capture AFTER INSERT ON approvals FOR EACH ROW EXECUTE FUNCTION forge_approval_event_trigger();
CREATE OR REPLACE FUNCTION forge_qa_event_trigger() RETURNS trigger AS $$ BEGIN PERFORM forge_capture_event('qa.result.recorded',(SELECT project_id FROM episodes WHERE id=NEW.episode_id),NEW.episode_id,'qa_result',NEW.id,jsonb_build_object('qaResultId',NEW.id,'episodeId',NEW.episode_id,'status',NEW.status,'artifactId',NEW.artifact_id)); RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_qa_event_capture ON qa_results; CREATE TRIGGER forge_qa_event_capture AFTER INSERT ON qa_results FOR EACH ROW EXECUTE FUNCTION forge_qa_event_trigger();
CREATE OR REPLACE FUNCTION forge_audit_event_trigger() RETURNS trigger AS $$ BEGIN IF NEW.project_id IS NOT NULL AND NEW.project_id IN (SELECT id FROM projects) THEN PERFORM forge_capture_event('security.audit.recorded',NEW.project_id,NEW.episode_id,'audit_event',NEW.id::text,jsonb_build_object('auditEventId',NEW.id,'tenantId',(SELECT tenant_id FROM projects WHERE id=NEW.project_id),'action',NEW.action,'outcome',NEW.outcome)); END IF; RETURN NEW; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS forge_audit_event_capture ON security_audit_events; CREATE TRIGGER forge_audit_event_capture AFTER INSERT ON security_audit_events FOR EACH ROW EXECUTE FUNCTION forge_audit_event_trigger();
COMMIT;
